{"original_issue": "把输入序列按给定容量分组，最后一组即使没有装满也不能丢掉元素。空序列返回空列表，容量小于等于0时应该报ValueError。", "api": [{"path": "stream_ops.py", "symbol": "split_packets", "type": "function", "is_target": true, "code": "def split_packets(values, size):
    if size <= 0:
        raise ValueError("size must be positive")
    return [values[i:i + size] for i in range(0, len(values) - size + 1, size)]"}], "public_tests": [{"path": "tests/test_public.py", "code": "import unittest
import stream_ops as api

class PublicTests(unittest.TestCase):
    def test_exact(self): self.assertEqual(api.split_packets([1,2,3,4],2), [[1,2],[3,4]])
    def test_empty(self): self.assertEqual(api.split_packets([],2), [])
    def test_invalid(self):
        with self.assertRaises(ValueError): api.split_packets([1],0)
    def test_flatten(self): self.assertEqual(api.flatten([[1],[2,3]]),[1,2,3])
